document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("pre > code").forEach(function(e){const n=e.parentNode;if(!n.parentNode)return;const s=document.createElement("div");s.className="code-block-wrapper",n.parentNode.insertBefore(s,n),s.appendChild(n);const t=document.createElement("button");t.className="copy-code-button",t.type="button",t.textContent="Copy code",s.appendChild(t),t.addEventListener("click",function(){if(!navigator.clipboard){t.textContent="Copy unavailable";return}navigator.clipboard.writeText(e.textContent).then(function(){t.textContent="Copied!"},function(e){console.error("Unable to copy code:",e),t.textContent="Copy failed"})})}),typeof renderMathInElement=="function"&&renderMathInElement(document.querySelector(".post-content"))})